args.Content:
import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173,
    proxy: {
      '/api': {
        target: 'http://127.0.0.1:8000',
        changeOrigin: true
      }
    }
  }
})

export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
}

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  body {
    @apply bg-navy-900 text-slate-100;
  }
}

/* Custom Scrollbar for Intelligence Interface */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: #090D16;
}

::-webkit-scrollbar-thumb {
  background: #1E293B;
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: #334155;
}

/* Restrained pulse animation */
@keyframes subtle-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.animate-subtle-pulse {
  animation: subtle-pulse 3s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}

export interface FeatureContribution {
  code: string;
  impact: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
  description: string;
  value: string;
}

export interface Transaction {
  transaction_id: string;
  timestamp: string;
  account_id: string;
  amount: number;
  currency: string;
  merchant_id?: string;
  merchant_category: string;
  device_id: string;
  ip_address: string;
  location_country: string;
  account_age_days: number;
  failed_attempts_last_24h: number;
  is_fraud_label?: number;
  risk_score: number;
  calibrated_prob: number;
  triage_category: 'HIGH RISK' | 'UNCERTAIN' | 'LOWER RISK';
  uncertainty_indicator: number;
  review_priority: number;
  model_version: string;
  investigation_status?: string;
  assigned_investigator?: string;
  feature_contributions?: FeatureContribution[];
  raw_features?: Record<string, any>;
  simulation_badge?: string;
}

export interface CaseSummary {
  observed_evidence: string[];
  main_score_contributors: string[];
  related_records: string;
  missing_information: string;
  uncertainty_analysis: string;
  recommended_verification_steps: string[];
}

export interface OverviewStatistics {
  summary: {
    total_analyzed: number;
    high_risk_cases: number;
    uncertain_cases: number;
    lower_risk_cases: number;
    confirmed_fraud_feedback: number;
    investigator_overrides: number;
  };
  evaluation_metrics: {
    held_out_test_records: number;
    held_out_test_fraud_cases: number;
    champion_model: {
      algorithm: string;
      precision: number;
      recall: number;
      f1_score: number;
      roc_auc: number;
      pr_auc: number;
      confusion_matrix: {
        true_negative: number;
        false_positive: number;
        false_negative: number;
        true_positive: number;
      };
      precision_at_capacity_top20: number;
    };
    baseline_model: {
      algorithm: string;
      precision: number;
      recall: number;
      f1_score: number;
      roc_auc: number;
    };
  };
  risk_distribution: Array<{
    category: string;
    count: number;
    percentage: number;
    color: string;
  }>;
  top_evidence_reasons: Array<{
    code: string;
    count: number;
    description: string;
  }>;
  model_metadata: {
    version: string;
    trained_date: string;
    train_samples: number;
    feature_columns: string[];
  };
  thresholds: {
    tau_low: number;
    tau_high: number;
  };
}

export interface CounterfactualResponse {
  transaction_id: string;
  model_version: string;
  original_risk_score: number;
  modified_risk_score: number;
  risk_score_delta: number;
  original_category: string;
  modified_category: string;
  changed_inputs: Record<string, { original: any; modified: any }>;
  interpretability_warning: string;
}

export interface ReplayTimelineEvent {
  transaction_id: string;
  timestamp: string;
  amount: number;
  merchant_category: string;
  device_id: string;
  risk_score: number;
  triage_category: string;
  leakage_classification: string;
  is_target: boolean;
}

export interface BehavioralChangeItem {
  signal: string;
  observation: string;
  neutral_assessment: string;
}

export interface GraphNode {
  id: string;
  node_type: 'transaction' | 'account' | 'device' | 'ip' | 'merchant';
  label: string;
  amount?: number;
  is_fraud?: number;
  account_count?: number;
}

export interface GraphEdge {
  source: string;
  target: string;
  relation: string;
  evidence: string;
}

export interface EgoGraphData {
  root_transaction: string;
  nodes: GraphNode[];
  edges: GraphEdge[];
  cluster_node_count: number;
  shared_devices: string[];
  shared_ips: string[];
  has_syndicate_overlap: boolean;
}

export interface SyndicateCluster {
  entity_type: string;
  entity_id: string;
  shared_account_count: number;
  accounts: string[];
  associated_transactions: string[];
  risk_level: string;
  narrative: string;
}

export interface FeedbackRecord {
  id: number;
  transaction_id: string;
  decision: string;
  reviewer_name: string;
  notes: string;
  model_version: string;
  original_model_score: number;
  original_category: string;
  is_override: number;
  created_at: string;
}

import {
  Transaction, OverviewStatistics, CaseSummary, CounterfactualResponse,
  ReplayTimelineEvent, BehavioralChangeItem, EgoGraphData, SyndicateCluster,
  FeedbackRecord
} from '../types';

const API_BASE = '/api';

export const api = {
  getOverview: async (): Promise<OverviewStatistics> => {
    const res = await fetch(`${API_BASE}/overview`);
    if (!res.ok) throw new Error('Failed to load overview data');
    return res.json();
  },

  getQueue: async (params: {
    triage_category?: string;
    min_risk?: number;
    status?: string;
    sort_by?: string;
    ascending?: boolean;
    limit?: number;
  }): Promise<{ total_returned: number; queue_sort_formula: string; items: Transaction[] }> => {
    const query = new URLSearchParams();
    if (params.triage_category) query.set('triage_category', params.triage_category);
    if (params.min_risk !== undefined) query.set('min_risk', params.min_risk.toString());
    if (params.status) query.set('status', params.status);
    if (params.sort_by) query.set('sort_by', params.sort_by);
    if (params.ascending !== undefined) query.set('ascending', params.ascending.toString());
    if (params.limit) query.set('limit', params.limit.toString());

    const res = await fetch(`${API_BASE}/queue?${query.toString()}`);
    if (!res.ok) throw new Error('Failed to load queue data');
    return res.json();
  },

  getTransactionDetail: async (id: string): Promise<{ transaction: Transaction; case_summary: CaseSummary }> => {
    const res = await fetch(`${API_BASE}/transactions/${id}`);
    if (!res.ok) throw new Error(`Failed to load transaction ${id}`);
    return res.json();
  },

  simulateCounterfactual: async (payload: {
    transaction_id: string;
    modified_amount?: number;
    modified_device_id?: string;
    modified_merchant_category?: string;
    modified_failed_attempts?: number;
    modified_country?: string;
  }): Promise<CounterfactualResponse> => {
    const res = await fetch(`${API_BASE}/replay/counterfactual`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    if (!res.ok) throw new Error('Counterfactual simulation failed');
    return res.json();
  },

  getReplayTimeline: async (id: string): Promise<{
    target_transaction_id: string;
    account_id: string;
    total_account_events: number;
    events: ReplayTimelineEvent[];
  }> => {
    const res = await fetch(`${API_BASE}/replay/timeline/${id}`);
    if (!res.ok) throw new Error('Failed to load replay timeline');
    return res.json();
  },

  getBehavioralChange: async (id: string): Promise<{
    transaction_id: string;
    account_id: string;
    prior_event_count: number;
    historical_average_amount: number;
    current_amount: number;
    behavioral_changes: BehavioralChangeItem[];
  }> => {
    const res = await fetch(`${API_BASE}/replay/behavioral-change/${id}`);
    if (!res.ok) throw new Error('Failed to load behavioral change analysis');
    return res.json();
  },

  getEgoGraph: async (id: string, depth = 2): Promise<EgoGraphData> => {
    const res = await fetch(`${API_BASE}/graph/ego/${id}?depth=${depth}`);
    if (!res.ok) throw new Error('Failed to load graph data');
    return res.json();
  },

  getSyndicates: async (): Promise<{ cluster_count: number; syndicates: SyndicateCluster[] }> => {
    const res = await fetch(`${API_BASE}/graph/syndicates`);
    if (!res.ok) throw new Error('Failed to load syndicate clusters');
    return res.json();
  },

  submitFeedback: async (feedback: {
    transaction_id: string;
    decision: string;
    reviewer_name: string;
    notes?: string;
  }): Promise<any> => {
    const res = await fetch(`${API_BASE}/feedback`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(feedback)
    });
    if (!res.ok) throw new Error('Failed to submit investigator decision');
    return res.json();
  },

  getFeedbackHistory: async (limit = 100): Promise<{ feedback_records: FeedbackRecord[] }> => {
    const res = await fetch(`${API_BASE}/feedback?limit=${limit}`);
    if (!res.ok) throw new Error('Failed to load feedback history');
    return res.json();
  },

  simulateQueueCapacity: async (daily_capacity: number): Promise<any> => {
    const res = await fetch(`${API_BASE}/queue/simulation`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ daily_review_capacity: daily_capacity })
    });
    if (!res.ok) throw new Error('Failed to simulate queue capacity');
    return res.json();
  },

  getDemoCases: async (): Promise<any> => {
    const res = await fetch(`${API_BASE}/demo/cases`);
    if (!res.ok) throw new Error('Failed to load demo cases');
    return res.json();
  },

  resetDemoData: async (): Promise<any> => {
    const res = await fetch(`${API_BASE}/demo/reset`, { method: 'POST' });
    if (!res.ok) throw new Error('Failed to reset demo data');
    return res.json();
  },

  uploadCsv: async (file: File): Promise<any> => {
    const formData = new FormData();
    formData.append('file', file);
    const res = await fetch(`${API_BASE}/upload-csv`, {
      method: 'POST',
      body: formData
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(err.detail || 'CSV upload failed');
    }
    return res.json();
  },

  getNextSimulatedEvent: async (): Promise<Transaction> => {
    const res = await fetch(`${API_BASE}/simulation/next-event`);
    if (!res.ok) throw new Error('Failed to emit simulated event');
    return res.json();
  }
};

import React, { useState } from 'react';
import { ShieldCheck, RefreshCw, Radio, Sparkles, AlertTriangle } from 'lucide-react';

interface NavbarProps {
  activeModelVersion: string;
  onResetDemo: () => void;
  onSelectDemoCase: (caseKey: 'case_a' | 'case_b' | 'case_c') => void;
  onToggleSimulation: () => void;
  isSimulating: boolean;
}

export const Navbar: React.FC<NavbarProps> = ({
  activeModelVersion,
  onResetDemo,
  onSelectDemoCase,
  onToggleSimulation,
  isSimulating,
}) => {
  const [resetting, setResetting] = useState(false);

  const handleReset = async () => {
    if (confirm('Reset demo transactions and feedback back to pristine factory benchmark?')) {
      setResetting(true);
      try {
        await onResetDemo();
      } finally {
        setResetting(false);
      }
    }
  };

  return (
    <header className="h-16 bg-navy-800 border-b border-slate-700/60 px-6 flex items-center justify-between sticky top-0 z-40 backdrop-blur-md">
      {/* Brand Identity */}
      <div className="flex items-center gap-3">
        <div className="w-10 h-10 rounded-lg bg-gradient-to-br from-cyan-500/20 to-teal-500/20 border border-cyan-500/40 flex items-center justify-center text-cyan-400 shadow-lg shadow-cyan-950/40">
          <ShieldCheck className="w-6 h-6 text-cyan-400" />
        </div>
        <div>
          <div className="flex items-center gap-2">
            <span className="font-bold text-lg tracking-tight bg-gradient-to-r from-slate-100 via-cyan-100 to-teal-200 bg-clip-text text-transparent">
              FraudLens AI
            </span>
            <span className="text-[10px] font-semibold uppercase px-2 py-0.5 rounded-full bg-cyan-950/80 text-cyan-300 border border-cyan-800/60 font-mono">
              Zeckathon PS2
            </span>
            <span className="text-[10px] font-semibold uppercase px-2 py-0.5 rounded-full bg-amber-950/60 text-amber-300 border border-amber-800/50 font-mono flex items-center gap-1">
              <span className="w-1.5 h-1.5 rounded-full bg-amber-400 animate-ping" />
              Synthetic Benchmark
            </span>
          </div>
          <p className="text-xs text-slate-400 hidden sm:block font-medium">
            Detect smarter. Explain every alert. Reduce false alarms.
          </p>
        </div>
      </div>

      {/* Operational Actions */}
      <div className="flex items-center gap-3">
        {/* Quick Demo Scenario Switcher */}
        <div className="hidden lg:flex items-center bg-slate-900 border border-slate-700 rounded-lg p-1 text-xs">
          <span className="px-2 text-slate-400 font-mono text-[11px] flex items-center gap-1">
            <Sparkles className="w-3.5 h-3.5 text-cyan-400" /> Demo Cases:
          </span>
          <button
            onClick={() => onSelectDemoCase('case_a')}
            className="px-2.5 py-1 rounded hover:bg-slate-800 text-slate-200 transition font-medium"
            title="Case A: Legitimate but unusual whale purchase on trusted device"
          >
            Case A <span className="text-emerald-400 text-[10px]">(Legit)</span>
          </button>
          <button
            onClick={() => onSelectDemoCase('case_b')}
            className="px-2.5 py-1 rounded hover:bg-slate-800 text-slate-200 transition font-medium"
            title="Case B: High-risk account takeover with multiple anomalies"
          >
            Case B <span className="text-rose-400 text-[10px]">(High Risk)</span>
          </button>
          <button
            onClick={() => onSelectDemoCase('case_c')}
            className="px-2.5 py-1 rounded hover:bg-slate-800 text-slate-200 transition font-medium"
            title="Case C: Multi-account device sharing fraud syndicate"
          >
            Case C <span className="text-amber-400 text-[10px]">(Syndicate)</span>
          </button>
        </div>

        {/* Live Simulation Mode Button */}
        <button
          onClick={onToggleSimulation}
          className={`px-3 py-1.5 rounded-lg text-xs font-semibold flex items-center gap-2 border transition ${
            isSimulating
              ? 'bg-rose-950/80 border-rose-600 text-rose-300 animate-pulse'
              : 'bg-slate-800 hover:bg-slate-700 border-slate-700 text-slate-200'
          }`}
        >
          <Radio className={`w-3.5 h-3.5 ${isSimulating ? 'text-rose-400' : 'text-slate-400'}`} />
          {isSimulating ? 'Live Feed Streaming' : 'Simulate Stream'}
        </button>

        {/* Reset Demo Data Button */}
        <button
          onClick={handleReset}
          disabled={resetting}
          className="px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-800 hover:bg-slate-700 border border-slate-700 text-slate-300 flex items-center gap-1.5 transition active:scale-95"
          title="Reset database to benchmark factory state"
        >
          <RefreshCw className={`w-3.5 h-3.5 ${resetting ? 'animate-spin text-cyan-400' : 'text-slate-400'}`} />
          <span className="hidden sm:inline">Reset Demo</span>
        </button>

        {/* Champion Model Badge */}
        <div className="hidden xl:flex items-center gap-2 px-3 py-1 rounded-lg bg-navy-900 border border-slate-700 text-xs font-mono text-slate-300">
          <span className="w-2 h-2 rounded-full bg-teal-400 animate-pulse" />
          <span>{activeModelVersion || 'v1.2.0-champion'}</span>
        </div>
      </div>
    </header>
  );
};

import React from 'react';
import {
  LayoutDashboard,
  ListFilter,
  FileSearch,
  Share2,
  History,
  BarChart3,
  CheckSquare,
  UploadCloud,
  ShieldAlert
} from 'lucide-react';

export type ScreenTab =
  | 'overview'
  | 'queue'
  | 'detail'
  | 'radar'
  | 'replay'
  | 'evaluation'
  | 'feedback'
  | 'upload'
  | 'model_info';

interface SidebarProps {
  activeTab: ScreenTab;
  onTabChange: (tab: ScreenTab) => void;
  highRiskCount: number;
  uncertainCount: number;
}

export const Sidebar: React.FC<SidebarProps> = ({
  activeTab,
  onTabChange,
  highRiskCount,
  uncertainCount,
}) => {
  const menuItems = [
    {
      id: 'overview' as ScreenTab,
      label: 'Overview Dashboard',
      icon: LayoutDashboard,
      badge: null,
    },
    {
      id: 'queue' as ScreenTab,
      label: 'Investigation Queue',
      icon: ListFilter,
      badge: highRiskCount > 0 ? `${highRiskCount} alerts` : null,
      badgeColor: 'bg-rose-950 text-rose-300 border-rose-800',
    },
    {
      id: 'detail' as ScreenTab,
      label: 'Transaction Detail',
      icon: FileSearch,
      badge: null,
    },
    {
      id: 'replay' as ScreenTab,
      label: 'FraudLens Replay Lab',
      icon: History,
      badge: 'Core Feature',
      badgeColor: 'bg-cyan-950 text-cyan-300 border-cyan-800',
    },
    {
      id: 'radar' as ScreenTab,
      label: 'Fraud Network Radar',
      icon: Share2,
      badge: null,
    },
    {
      id: 'evaluation' as ScreenTab,
      label: 'Model Evaluation',
      icon: BarChart3,
      badge: 'Metrics',
      badgeColor: 'bg-teal-950 text-teal-300 border-teal-800',
    },
    {
      id: 'feedback' as ScreenTab,
      label: 'Audit & Feedback',
      icon: CheckSquare,
      badge: null,
    },
    {
      id: 'upload' as ScreenTab,
      label: 'Dataset CSV Ingestion',
      icon: UploadCloud,
      badge: null,
    },
    {
      id: 'model_info' as ScreenTab,
      label: 'Model & Governance',
      icon: ShieldAlert,
      badge: null,
