                <th className="py-3 px-4">TIMESTAMP</th>
                <th className="py-3 px-4 text-right">AMOUNT</th>
                <th className="py-3 px-4 text-center">TRIAGE</th>
                <th className="py-3 px-4 text-center">RISK SCORE</th>
                <th className="py-3 px-4 text-center">UNCERTAINTY</th>
                <th className="py-3 px-4 text-center">PRIORITY</th>
                <th className="py-3 px-4">PRIMARY REASON</th>
                <th className="py-3 px-4 text-center">STATUS</th>
                <th className="py-3 px-4 text-right">ACTION</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800 text-slate-200">
              {loading ? (
                <tr>
                  <td colSpan={10} className="py-12 text-center text-slate-400 font-mono">
                    Loading verified transaction records...
                  </td>
                </tr>
              ) : filteredItems.length === 0 ? (
                <tr>
                  <td colSpan={10} className="py-12 text-center text-slate-400">
                    No transactions match current filters.
                  </td>
                </tr>
              ) : (
                filteredItems.map((item) => {
                  const primaryReason =
                    item.feature_contributions && item.feature_contributions.length > 0
                      ? item.feature_contributions[0]
                      : null;

                  return (
                    <tr
                      key={item.transaction_id}
                      onClick={() => onSelectTransaction(item.transaction_id)}
                      className="hover:bg-slate-800/80 transition cursor-pointer group"
                    >
                      <td className="py-3 px-4 font-mono font-medium text-cyan-300">
                        {item.transaction_id}
                      </td>
                      <td className="py-3 px-4 text-slate-400 text-[11px] font-mono">
                        {new Date(item.timestamp).toLocaleString(undefined, {
                          month: 'short',
                          day: 'numeric',
                          hour: '2-digit',
                          minute: '2-digit',
                        })}
                      </td>
                      <td className="py-3 px-4 text-right font-mono font-bold text-slate-100">
                        ${item.amount.toFixed(2)}
                      </td>
                      <td className="py-3 px-4 text-center">
                        <span
                          className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full font-mono font-semibold text-[10px] border ${
                            item.triage_category === 'HIGH RISK'
                              ? 'bg-rose-950/80 text-rose-300 border-rose-800'
                              : item.triage_category === 'UNCERTAIN'
                              ? 'bg-amber-950/80 text-amber-300 border-amber-800'
                              : 'bg-emerald-950/80 text-emerald-300 border-emerald-800'
                          }`}
                        >
                          {item.triage_category === 'HIGH RISK' && (
                            <ShieldAlert className="w-3 h-3 text-rose-400" />
                          )}
                          {item.triage_category === 'UNCERTAIN' && (
                            <HelpCircle className="w-3 h-3 text-amber-400" />
                          )}
                          {item.triage_category === 'LOWER RISK' && (
                            <ShieldCheck className="w-3 h-3 text-emerald-400" />
                          )}
                          {item.triage_category}
                        </span>
                      </td>
                      <td className="py-3 px-4 text-center font-mono font-bold">
                        <span
                          className={
                            item.risk_score >= 65
                              ? 'text-rose-400'
                              : item.risk_score >= 20
                              ? 'text-amber-400'
                              : 'text-emerald-400'
                          }
                        >
                          {item.risk_score.toFixed(1)}
                        </span>
                      </td>
                      <td className="py-3 px-4 text-center font-mono text-slate-300">
                        {item.uncertainty_indicator.toFixed(2)}
                      </td>
                      <td className="py-3 px-4 text-center font-mono font-bold text-cyan-300">
                        {item.review_priority.toFixed(1)}
                      </td>
                      <td className="py-3 px-4 text-slate-300">
                        {primaryReason ? (
                          <div className="truncate max-w-xs">
                            <span className="font-mono text-[10px] text-slate-400 block">
                              {primaryReason.code}
                            </span>
                            <span className="text-[11px] text-slate-300">{primaryReason.description}</span>
                          </div>
                        ) : (
                          <span className="text-slate-500 font-mono text-[11px]">Baseline Normal</span>
                        )}
                      </td>
                      <td className="py-3 px-4 text-center">
                        <span
                          className={`text-[10px] font-mono px-2 py-0.5 rounded capitalize ${
                            item.investigation_status === 'confirmed_fraud'
                              ? 'bg-rose-900/60 text-rose-300'
                              : item.investigation_status === 'legitimate'
                              ? 'bg-teal-900/60 text-teal-300'
                              : 'bg-slate-800 text-slate-400'
                          }`}
                        >
                          {item.investigation_status?.replace('_', ' ') || 'Pending'}
                        </span>
                      </td>
                      <td className="py-3 px-4 text-right">
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            onSelectTransaction(item.transaction_id);
                          }}
                          className="px-2.5 py-1 rounded bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs flex items-center gap-1 ml-auto transition"
                        >
                          <span>Inspect</span>
                          <ExternalLink className="w-3 h-3 text-cyan-400" />
                        </button>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import {
  ShieldAlert,
  HelpCircle,
  ShieldCheck,
  History,
  CheckSquare,
  AlertCircle,
  ExternalLink,
  ChevronRight,
  UserCheck,
  XCircle,
  ArrowRight,
  Info
} from 'lucide-react';
import { Transaction, CaseSummary } from '../types';
import { api } from '../services/api';

interface TransactionDetailProps {
  transactionId: string;
  onNavigateToReplay: (id: string) => void;
  onNavigateToRadar: (id: string) => void;
  onDecisionSubmitted: () => void;
}

export const TransactionDetail: React.FC<TransactionDetailProps> = ({
  transactionId,
  onNavigateToReplay,
  onNavigateToRadar,
  onDecisionSubmitted,
}) => {
  const [data, setData] = useState<{ transaction: Transaction; case_summary: CaseSummary } | null>(null);
  const [loading, setLoading] = useState(true);

  // Feedback modal / form state
  const [decision, setDecision] = useState<'confirmed_fraud' | 'legitimate' | 'inconclusive' | 'escalated'>('confirmed_fraud');
  const [reviewerName, setReviewerName] = useState<string>('Senior Investigator');
  const [notes, setNotes] = useState<string>('');
  const [submitting, setSubmitting] = useState(false);
  const [successMsg, setSuccessMsg] = useState<string>('');

  const loadDetail = async () => {
    setLoading(true);
    try {
      const res = await api.getTransactionDetail(transactionId);
      setData(res);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (transactionId) {
      loadDetail();
    }
  }, [transactionId]);

  const handleSubmitDecision = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubmitting(true);
    try {
      await api.submitFeedback({
        transaction_id: transactionId,
        decision,
        reviewer_name: reviewerName,
        notes,
      });
      setSuccessMsg(`Decision '${decision.replace('_', ' ').toUpperCase()}' logged to audit history.`);
      onDecisionSubmitted();
      loadDetail();
      setTimeout(() => setSuccessMsg(''), 4000);
    } catch (err) {
      alert('Failed to submit decision: ' + err);
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96 font-mono text-cyan-400 text-sm">
        <div className="w-5 h-5 border-2 border-cyan-400 border-t-transparent rounded-full animate-spin mr-3" />
        Loading transaction audit profile...
      </div>
    );
  }

  if (!data) {
    return (
      <div className="p-8 text-center text-slate-400">
        <AlertCircle className="w-12 h-12 text-rose-400 mx-auto mb-2" />
        Transaction not found or could not be loaded.
      </div>
    );
  }

  const { transaction: txn, case_summary: summary } = data;

  return (
    <div className="space-y-6">
      {/* Top Breadcrumb & Action Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-2 border-b border-slate-700/60">
        <div className="flex items-center gap-3">
          <span className="text-xl font-bold font-mono text-cyan-300">
            {txn.transaction_id}
          </span>
          <span
            className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full font-mono font-bold text-xs border ${
              txn.triage_category === 'HIGH RISK'
                ? 'bg-rose-950/80 text-rose-300 border-rose-800'
                : txn.triage_category === 'UNCERTAIN'
                ? 'bg-amber-950/80 text-amber-300 border-amber-800'
                : 'bg-emerald-950/80 text-emerald-300 border-emerald-800'
            }`}
          >
            {txn.triage_category === 'HIGH RISK' && <ShieldAlert className="w-3.5 h-3.5" />}
            {txn.triage_category === 'UNCERTAIN' && <HelpCircle className="w-3.5 h-3.5" />}
            {txn.triage_category === 'LOWER RISK' && <ShieldCheck className="w-3.5 h-3.5" />}
            {txn.triage_category}
          </span>
        </div>

        {/* Action Jump to Replay Lab */}
        <div className="flex items-center gap-2">
          <button
            onClick={() => onNavigateToRadar(txn.transaction_id)}
            className="px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-800 hover:bg-slate-700 border border-slate-700 text-slate-200 flex items-center gap-1.5 transition"
          >
            <span>Network Radar</span>
          </button>
          <button
            onClick={() => onNavigateToReplay(txn.transaction_id)}
            className="px-4 py-1.5 rounded-lg text-xs font-semibold bg-gradient-to-r from-cyan-600 to-teal-600 hover:from-cyan-500 hover:to-teal-500 text-white flex items-center gap-2 shadow-md shadow-cyan-950/40 transition"
          >
            <History className="w-4 h-4" />
            <span>Open in Replay Lab</span>
          </button>
        </div>
      </div>

      {/* Triage Calculation Cards Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {/* Fraud Risk Score */}
        <div className="bg-slate-850 p-4 rounded-xl border border-slate-700/80">
          <span className="text-[11px] text-slate-400 block font-mono">ESTIMATED FRAUD SCORE</span>
          <div className="flex items-baseline gap-2 mt-1">
            <span
              className={`text-3xl font-bold font-mono ${
                txn.risk_score >= 65
                  ? 'text-rose-400'
                  : txn.risk_score >= 20
                  ? 'text-amber-400'
                  : 'text-emerald-400'
              }`}
            >
              {txn.risk_score.toFixed(1)}
            </span>
            <span className="text-xs text-slate-400 font-mono">/ 100</span>
          </div>
          <span className="text-[10px] text-slate-400 mt-1 block">
            Calibrated prob: {(txn.calibrated_prob * 100).toFixed(2)}%
          </span>
        </div>

        {/* Uncertainty Indicator */}
        <div className="bg-slate-850 p-4 rounded-xl border border-slate-700/80">
          <div className="flex items-center justify-between">
            <span className="text-[11px] text-slate-400 font-mono">UNCERTAINTY RATING</span>
            <span className="text-[10px] font-mono text-cyan-400">Boundary Metric</span>
          </div>
          <div className="flex items-baseline gap-2 mt-1">
            <span className="text-3xl font-bold font-mono text-amber-400">
              {txn.uncertainty_indicator.toFixed(2)}
            </span>
            <span className="text-xs text-slate-400 font-mono">/ 1.00</span>
          </div>
          <span className="text-[10px] text-slate-400 mt-1 block">
            Margin to decision boundary: {Math.abs(txn.calibrated_prob - 0.5) * 2 > 0.4 ? 'Wide (Confident)' : 'Narrow (Ambiguous)'}
          </span>
        </div>

        {/* Operational Review Priority */}
        <div className="bg-slate-850 p-4 rounded-xl border border-slate-700/80">
          <span className="text-[11px] text-slate-400 block font-mono">REVIEW PRIORITY</span>
          <div className="flex items-baseline gap-2 mt-1">
            <span className="text-3xl font-bold font-mono text-cyan-300">
              {txn.review_priority.toFixed(1)}
            </span>
            <span className="text-xs text-slate-400 font-mono">Ranked</span>
          </div>
          <span className="text-[10px] text-slate-400 mt-1 block">
            Combines risk, uncertainty & ${txn.amount.toFixed(0)} exposure
          </span>
        </div>

        {/* Active Investigation Status */}
        <div className="bg-slate-850 p-4 rounded-xl border border-slate-700/80">
          <span className="text-[11px] text-slate-400 block font-mono">CASE STATUS</span>
          <div className="mt-1">
            <span className="text-lg font-bold font-mono capitalize text-slate-200">
              {txn.investigation_status?.replace('_', ' ') || 'Pending Review'}
            </span>
          </div>
          <span className="text-[10px] text-slate-400 mt-1 block">
            Reviewer: {txn.assigned_investigator || 'Unassigned'}
          </span>
        </div>
      </div>

      {/* Main Analysis Dual Pane */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column: Evidence & Reason Codes */}
        <div className="lg:col-span-2 space-y-6">
          {/* Feature Contribution Reason Codes */}
          <div className="bg-slate-850 border border-slate-700/80 rounded-xl p-5 space-y-3">
            <h2 className="text-sm font-bold text-slate-200 flex items-center gap-2">
              <ShieldAlert className="w-4 h-4 text-cyan-400" />
              Transparent Feature Contributions & Reasons
            </h2>
            <div className="space-y-2">
              {txn.feature_contributions?.map((fc, idx) => (
                <div
                  key={idx}
                  className="p-3 bg-slate-900 rounded-lg border border-slate-800 flex items-start justify-between gap-3 text-xs"
                >
                  <div className="space-y-1">
                    <div className="flex items-center gap-2">
                      <span className="font-mono font-bold text-cyan-300">{fc.code}</span>
                      <span
                        className={`text-[9px] font-mono px-1.5 py-0.2 rounded font-bold uppercase ${
                          fc.impact === 'CRITICAL'
                            ? 'bg-rose-950 text-rose-300 border border-rose-800'
                            : fc.impact === 'HIGH'
                            ? 'bg-amber-950 text-amber-300 border border-amber-800'
                            : 'bg-slate-800 text-slate-300'
                        }`}
                      >
                        {fc.impact}
                      </span>
                    </div>
                    <p className="text-slate-300 text-[11px]">{fc.description}</p>
                  </div>
                  <span className="font-mono text-slate-400 shrink-0 text-right">{fc.value}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Evidence-Grounded Case Summary (Zero Generative Hallucinations) */}
          <div className="bg-slate-850 border border-slate-700/80 rounded-xl p-5 space-y-4">
            <h2 className="text-sm font-bold text-slate-200 flex items-center gap-2">
              <Info className="w-4 h-4 text-teal-400" />
              Evidence-Grounded Case Summary
            </h2>

            <div className="space-y-3 text-xs">
              <div>
                <span className="font-semibold text-slate-300 block mb-1 font-mono text-[11px]">
                  [1] OBSERVED EVIDENCE
                </span>
                <ul className="space-y-1 text-slate-400 pl-2">
                  {summary.observed_evidence.map((ev, i) => (
                    <li key={i}>{ev}</li>
                  ))}
                </ul>
              </div>

              <div>
                <span className="font-semibold text-slate-300 block mb-1 font-mono text-[11px]">
                  [2] UNCERTAINTY & BOUNDARY DISTANCE
                </span>
                <p className="text-slate-400 pl-2">{summary.uncertainty_analysis}</p>
              </div>

              <div>
                <span className="font-semibold text-slate-300 block mb-1 font-mono text-[11px]">
                  [3] RECOMMENDED VERIFICATION WORKFLOW
                </span>
                <div className="p-3 bg-slate-900 rounded-lg border border-slate-800 space-y-1.5 pl-3">
                  {summary.recommended_verification_steps.map((step, idx) => (
                    <div key={idx} className="text-slate-300 font-mono text-[11px]">
                      {step}
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Right Column: Transaction Properties & Decision Recording */}
        <div className="space-y-6">
          {/* Transaction Metadata Card */}
          <div className="bg-slate-850 border border-slate-700/80 rounded-xl p-5 space-y-3">
            <h3 className="text-xs font-bold text-slate-300 font-mono uppercase tracking-wider">
              Transaction Metadata
            </h3>
            <div className="divide-y divide-slate-800 text-xs">
              <div className="py-2 flex justify-between">
                <span className="text-slate-400">Account ID</span>
                <span className="font-mono text-slate-200">{txn.account_id}</span>
              </div>
              <div className="py-2 flex justify-between">
                <span className="text-slate-400">Timestamp</span>
                <span className="font-mono text-slate-200">{txn.timestamp}</span>
              </div>
              <div className="py-2 flex justify-between">
                <span className="text-slate-400">Amount</span>
                <span className="font-mono font-bold text-slate-100">${txn.amount.toFixed(2)}</span>
              </div>
              <div className="py-2 flex justify-between">
                <span className="text-slate-400">Merchant Category</span>
                <span className="capitalize text-slate-200">{txn.merchant_category}</span>
              </div>
              <div className="py-2 flex justify-between">
                <span className="text-slate-400">Device Fingerprint</span>
                <span className="font-mono text-cyan-300">{txn.device_id}</span>
              </div>
              <div className="py-2 flex justify-between">
                <span className="text-slate-400">IP Address</span>
                <span className="font-mono text-slate-200">{txn.ip_address}</span>
              </div>
              <div className="py-2 flex justify-between">
                <span className="text-slate-400">Country Origin</span>
                <span className="font-mono text-slate-200">{txn.location_country}</span>
              </div>
              <div className="py-2 flex justify-between">
                <span className="text-slate-400">Account Age</span>
                <span className="text-slate-200">{txn.account_age_days} days</span>
              </div>
              <div className="py-2 flex justify-between">
                <span className="text-slate-400">Failed Logins (24h)</span>
                <span className="font-mono text-slate-200">{txn.failed_attempts_last_24h}</span>
              </div>
            </div>
          </div>

          {/* Record Investigator Decision Form */}
          <div className="bg-slate-850 border border-slate-700/80 rounded-xl p-5 space-y-4">
            <div className="flex items-center gap-2">
              <CheckSquare className="w-4 h-4 text-teal-400" />
              <h3 className="text-xs font-bold text-slate-200 uppercase tracking-wider font-mono">
                Record Investigator Decision
              </h3>
            </div>

            {successMsg && (
              <div className="p-2.5 rounded bg-teal-950/80 border border-teal-700 text-teal-300 text-xs font-medium">
                {successMsg}
              </div>
            )}

            <form onSubmit={handleSubmitDecision} className="space-y-3 text-xs">
              <div>
                <label className="block text-slate-400 mb-1 font-mono text-[11px]">
                  AUDIT DECISION
                </label>
                <select
                  value={decision}
                  onChange={(e: any) => setDecision(e.target.value)}
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg p-2 text-slate-100 outline-none"
                >
                  <option value="confirmed_fraud">Confirmed Fraud</option>
                  <option value="legitimate">Legitimate Transaction</option>
                  <option value="inconclusive">Inconclusive / More Data</option>
                  <option value="escalated">Escalated to Tier 3</option>
                </select>
              </div>

              <div>
                <label className="block text-slate-400 mb-1 font-mono text-[11px]">
                  REVIEWER IDENTITY
                </label>
                <input
                  type="text"
                  value={reviewerName}
                  onChange={(e) => setReviewerName(e.target.value)}
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg p-2 text-slate-100 outline-none"
                />
              </div>

              <div>
                <label className="block text-slate-400 mb-1 font-mono text-[11px]">
                  AUDIT NOTES & RATIONALE
                </label>
                <textarea
                  rows={3}
                  placeholder="Record verification notes, out-of-band checks, or customer conversation summary..."
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg p-2 text-slate-100 outline-none resize-none"
                />
              </div>

              <button
                type="submit"
                disabled={submitting}
                className="w-full py-2 rounded-lg bg-teal-600 hover:bg-teal-500 font-semibold text-white transition text-xs flex items-center justify-center gap-1.5 active:scale-98"
              >
                {submitting ? 'Persisting Decision...' : 'Commit Audit Decision'}
              </button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import {
  History,
  Sliders,
  TrendingUp,
  AlertCircle,
  HelpCircle,
  ShieldCheck,
  ShieldAlert,
  Clock,
  ArrowRight,
  Sparkles,
  Info,
  RotateCcw,
  CheckCircle2
} from 'lucide-react';
import {
  Transaction,
  ReplayTimelineEvent,
  BehavioralChangeItem,
  CounterfactualResponse
} from '../types';
import { api } from '../services/api';

interface ReplayLabProps {
  transactionId: string;
  onSelectTransaction: (id: string) => void;
}

export const ReplayLab: React.FC<ReplayLabProps> = ({
  transactionId,
  onSelectTransaction,
}) => {
  const [activeSubTab, setActiveSubTab] = useState<'timeline' | 'behavior' | 'counterfactual' | 'summary'>('timeline');
  const [loading, setLoading] = useState(true);

  // Data states
  const [timelineEvents, setTimelineEvents] = useState<ReplayTimelineEvent[]>([]);
  const [behavioralChanges, setBehavioralChanges] = useState<BehavioralChangeItem[]>([]);
  const [histAvg, setHistAvg] = useState<number>(0);
  const [currAmount, setCurrAmount] = useState<number>(0);

  // Counterfactual Interactive States
  const [cfAmount, setCfAmount] = useState<number>(0);
  const [cfFailedAttempts, setCfFailedAttempts] = useState<number>(0);
  const [cfCategory, setCfCategory] = useState<string>('grocery');
  const [cfResult, setCfResult] = useState<CounterfactualResponse | null>(null);
  const [cfLoading, setCfLoading] = useState(false);

  const loadReplayData = async () => {
    setLoading(true);
    try {
      const [tlRes, bcRes, txnRes] = await Promise.all([
        api.getReplayTimeline(transactionId),
        api.getBehavioralChange(transactionId),
        api.getTransactionDetail(transactionId)
      ]);

      setTimelineEvents(tlRes.events);
      setBehavioralChanges(bcRes.behavioral_changes);
      setHistAvg(bcRes.historical_average_amount);
      setCurrAmount(bcRes.current_amount);

      // Initialize counterfactual inputs with current transaction values
      const currentTxn = txnRes.transaction;
      setCfAmount(currentTxn.amount);
      setCfFailedAttempts(currentTxn.failed_attempts_last_24h);
      setCfCategory(currentTxn.merchant_category);

      // Run initial counterfactual
      const cfInit = await api.simulateCounterfactual({
        transaction_id: transactionId,
        modified_amount: currentTxn.amount,
        modified_failed_attempts: currentTxn.failed_attempts_last_24h,
        modified_merchant_category: currentTxn.merchant_category,
      });
      setCfResult(cfInit);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (transactionId) {
      loadReplayData();
    }
  }, [transactionId]);

  const handleRunCounterfactual = async () => {
    setCfLoading(true);
    try {
      const res = await api.simulateCounterfactual({
        transaction_id: transactionId,
        modified_amount: cfAmount,
        modified_failed_attempts: cfFailedAttempts,
        modified_merchant_category: cfCategory,
      });
      setCfResult(res);
    } catch (err) {
      console.error(err);
    } finally {
      setCfLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96 font-mono text-cyan-400 text-sm">
        <div className="w-5 h-5 border-2 border-cyan-400 border-t-transparent rounded-full animate-spin mr-3" />
        Initializing FraudLens Replay Lab environment...
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header Banner */}
      <div className="bg-gradient-to-r from-navy-800 via-slate-850 to-navy-850 border border-cyan-500/30 rounded-xl p-5 shadow-lg">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <div className="flex items-center gap-2">
              <span className="p-1 rounded bg-cyan-950 border border-cyan-800 text-cyan-400 font-mono text-[10px] font-bold">
                CORE INNOVATION
              </span>
              <h1 className="text-xl font-bold tracking-tight text-slate-100 flex items-center gap-2">
                FraudLens Replay Lab
              </h1>
            </div>
            <p className="text-xs text-slate-400 mt-1">
              Active Target: <span className="font-mono text-cyan-300 font-bold">{transactionId}</span> — Deep chronological forensics, behavioral anomaly isolation, and counterfactual stress testing.
            </p>
          </div>

          {/* Navigation Sub-Tabs */}
          <div className="flex items-center bg-slate-900 border border-slate-700/80 rounded-lg p-1 text-xs">
            <button
              onClick={() => setActiveSubTab('timeline')}
              className={`px-3 py-1.5 rounded-md font-medium transition ${
                activeSubTab === 'timeline'
                  ? 'bg-cyan-500/20 text-cyan-300 border border-cyan-500/30'
                  : 'text-slate-400 hover:text-slate-200'
              }`}
            >
              Timeline Replay
            </button>
            <button
              onClick={() => setActiveSubTab('behavior')}
              className={`px-3 py-1.5 rounded-md font-medium transition ${
                activeSubTab === 'behavior'
                  ? 'bg-cyan-500/20 text-cyan-300 border border-cyan-500/30'
                  : 'text-slate-400 hover:text-slate-200'
              }`}
            >
              Behavioral Drift
            </button>
            <button
              onClick={() => setActiveSubTab('counterfactual')}
              className={`px-3 py-1.5 rounded-md font-medium transition ${
                activeSubTab === 'counterfactual'
                  ? 'bg-cyan-500/20 text-cyan-300 border border-cyan-500/30'
                  : 'text-slate-400 hover:text-slate-200'
              }`}
            >
              What-If Simulator
            </button>
          </div>
        </div>
      </div>

      {/* SUB-TAB 1: Chronological Replay Timeline */}
      {activeSubTab === 'timeline' && (
        <div className="space-y-4">
          <div className="flex items-center justify-between text-xs text-slate-400 px-1">
            <span className="font-mono">
              Displaying {timelineEvents.length} account events in chronological order.
            </span>
            <div className="flex items-center gap-4 text-[11px] font-mono">
              <span className="flex items-center gap-1.5 text-teal-400">
                <span className="w-2 h-2 rounded-full bg-teal-400" />
                Historical Evidence (Prediction Time)
              </span>
              <span className="flex items-center gap-1.5 text-amber-400">
                <span className="w-2 h-2 rounded-full bg-amber-400" />
                Subsequent Event (Potential Lookahead Leakage)
              </span>
            </div>
          </div>

          <div className="relative pl-6 space-y-4 before:content-[''] before:absolute before:left-2.5 before:top-3 before:bottom-3 before:w-0.5 before:bg-slate-700/80">
            {timelineEvents.map((ev) => {
              const isTarget = ev.is_target;
              const isPrior = ev.leakage_classification === 'HISTORICAL_AVAILABLE_AT_PREDICTION';

              return (
                <div
                  key={ev.transaction_id}
                  onClick={() => onSelectTransaction(ev.transaction_id)}
                  className={`relative p-4 rounded-xl border transition cursor-pointer ${
                    isTarget
                      ? 'bg-cyan-950/40 border-cyan-500/70 shadow-lg shadow-cyan-950/50'
                      : 'bg-slate-850 hover:bg-slate-800 border-slate-700/80'
                  }`}
                >
                  {/* Timeline Bullet */}
                  <div
                    className={`absolute -left-6 top-5 w-4 h-4 rounded-full border-2 -translate-x-1/2 flex items-center justify-center ${
                      isTarget
                        ? 'bg-cyan-400 border-navy-900 ring-4 ring-cyan-500/30'
                        : isPrior
                        ? 'bg-teal-400 border-navy-900'
                        : 'bg-amber-400 border-navy-900'
                    }`}
                  />

                  <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 text-xs">
                    <div className="flex items-center gap-3">
                      <span className="font-mono font-bold text-slate-100">{ev.transaction_id}</span>
                      {isTarget && (
                        <span className="px-2 py-0.5 rounded bg-cyan-950 text-cyan-300 font-mono text-[10px] font-bold border border-cyan-800">
                          TARGET ALERT
                        </span>
                      )}
                      <span
                        className={`text-[10px] font-mono px-2 py-0.5 rounded ${
                          isPrior ? 'text-teal-400 bg-teal-950/60' : 'text-amber-400 bg-amber-950/60'
                        }`}
                      >
                        {isPrior ? 'Prior Baseline Event' : 'Later Observation'}
                      </span>
                    </div>

                    <div className="flex items-center gap-4 font-mono">
                      <span className="text-slate-400">{ev.timestamp}</span>
                      <span className="text-sm font-bold text-slate-100">${ev.amount.toFixed(2)}</span>
                      <span
                        className={`font-semibold ${
                          ev.risk_score >= 65 ? 'text-rose-400' : 'text-teal-400'
                        }`}
                      >
                        Score: {ev.risk_score?.toFixed(1) || 'N/A'}
                      </span>
                    </div>
                  </div>

                  <div className="mt-2 text-slate-400 text-[11px] grid grid-cols-2 sm:grid-cols-4 gap-2 pt-2 border-t border-slate-800">
                    <div>
                      Category: <span className="text-slate-200 capitalize">{ev.merchant_category}</span>
                    </div>
                    <div>
                      Device: <span className="text-slate-200 font-mono">{ev.device_id}</span>
                    </div>
                    <div>
                      Triage: <span className="text-slate-200">{ev.triage_category}</span>
                    </div>
                    <div>
                      Leakage Check: <span className="text-slate-300 font-mono">{ev.leakage_classification}</span>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* SUB-TAB 2: Behavioral Drift / Anomaly Isolation */}
      {activeSubTab === 'behavior' && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div className="bg-slate-850 p-4 rounded-xl border border-slate-700/80">
              <span className="text-[11px] text-slate-400 font-mono block">VERIFIED HISTORICAL AVG</span>
              <span className="text-2xl font-bold font-mono text-slate-100 mt-1 block">
                ${histAvg.toFixed(2)}
              </span>
              <span className="text-[10px] text-slate-400 mt-1 block">Account verified benchmark</span>
            </div>

            <div className="bg-slate-850 p-4 rounded-xl border border-slate-700/80">
              <span className="text-[11px] text-slate-400 font-mono block">CURRENT TRANSACTION</span>
              <span className="text-2xl font-bold font-mono text-cyan-300 mt-1 block">
                ${currAmount.toFixed(2)}
              </span>
              <span className="text-[10px] text-slate-400 mt-1 block">
                Ratio: {(currAmount / Math.max(histAvg, 1)).toFixed(1)}x baseline
              </span>
            </div>

            <div className="bg-slate-850 p-4 rounded-xl border border-slate-700/80">
              <span className="text-[11px] text-slate-400 font-mono block">DRIFT SEVERITY</span>
              <span
                className={`text-2xl font-bold font-mono mt-1 block ${
                  currAmount / Math.max(histAvg, 1) >= 3.0 ? 'text-rose-400' : 'text-teal-400'
                }`}
              >
                {currAmount / Math.max(histAvg, 1) >= 3.0 ? 'SIGNIFICANT' : 'NOMINAL'}
              </span>
              <span className="text-[10px] text-slate-400 mt-1 block">Neutral statistical evaluation</span>
            </div>
          </div>

          <div className="bg-slate-850 border border-slate-700/80 rounded-xl p-5 space-y-4">
            <h2 className="text-sm font-bold text-slate-200 flex items-center gap-2">
              <TrendingUp className="w-4 h-4 text-teal-400" />
              Documented Behavioral Anomaly Breakdown
            </h2>

            <div className="space-y-3">
              {behavioralChanges.map((change, idx) => (
                <div
                  key={idx}
                  className="p-3.5 bg-slate-900 rounded-lg border border-slate-800 space-y-1.5 text-xs"
                >
                  <div className="flex items-center justify-between font-mono font-bold text-cyan-300">
                    <span>{change.signal}</span>
                    <span className="text-[10px] font-normal text-slate-400">Signal #{idx + 1}</span>
                  </div>
                  <p className="text-slate-200 font-medium">{change.observation}</p>
                  <div className="p-2 rounded bg-slate-850/80 border border-slate-800 text-[11px] text-slate-400 flex items-start gap-2">
                    <Info className="w-3.5 h-3.5 text-slate-400 shrink-0 mt-0.5" />
                    <span>{change.neutral_assessment}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* SUB-TAB 3: Interactive What-If Counterfactual Simulator */}
      {activeSubTab === 'counterfactual' && (
        <div className="space-y-6">
          <div className="bg-slate-850 border border-slate-700/80 rounded-xl p-5 space-y-4">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
              <div>
                <h2 className="text-sm font-bold text-slate-200 flex items-center gap-2">
                  <Sliders className="w-4 h-4 text-cyan-400" />
                  What-If Counterfactual Signal Modeler
                </h2>
                <p className="text-xs text-slate-400 mt-0.5">
                  Simulate alternative realities: "What if the amount were closer to historical average?" or "What if failed logins were zero?"
                </p>
              </div>

              <button
                onClick={handleRunCounterfactual}
                disabled={cfLoading}
                className="px-4 py-2 rounded-lg bg-cyan-600 hover:bg-cyan-500 font-semibold text-white text-xs flex items-center gap-2 transition active:scale-95 shrink-0"
              >
                <Sparkles className="w-3.5 h-3.5" />
                {cfLoading ? 'Re-scoring Model...' : 'Recalculate Output'}
              </button>
            </div>

            {/* Signal Control Sliders */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 pt-2">
              {/* Amount Slider */}
              <div className="p-4 bg-slate-900 rounded-xl border border-slate-800 space-y-2">
                <div className="flex justify-between text-xs font-mono">
                  <span className="text-slate-400">Simulated Amount</span>
                  <span className="text-cyan-300 font-bold">${cfAmount.toFixed(2)}</span>
                </div>
                <input
                  type="range"
                  min="20"
                  max="4000"
                  step="20"
                  value={cfAmount}
                  onChange={(e) => setCfAmount(parseFloat(e.target.value))}
                  className="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                />
                <div className="flex justify-between text-[10px] text-slate-500 font-mono">
                  <span>$20 (Micro)</span>
                  <span>Baseline: ${histAvg.toFixed(0)}</span>
                  <span>$4,000 (Spike)</span>
                </div>
              </div>

              {/* Failed Attempts Slider */}
              <div className="p-4 bg-slate-900 rounded-xl border border-slate-800 space-y-2">
                <div className="flex justify-between text-xs font-mono">
                  <span className="text-slate-400">Failed Attempts (24h)</span>
                  <span className="text-amber-400 font-bold">{cfFailedAttempts} attempts</span>
                </div>
                <input
                  type="range"
                  min="0"
                  max="5"
                  step="1"
                  value={cfFailedAttempts}
                  onChange={(e) => setCfFailedAttempts(parseInt(e.target.value))}
                  className="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-amber-400"
                />
                <div className="flex justify-between text-[10px] text-slate-500 font-mono">
                  <span>0 (Smooth login)</span>
                  <span>2 (Warning)</span>
                  <span>5 (Brute Force)</span>
                </div>
              </div>

              {/* Merchant Category Select */}
              <div className="p-4 bg-slate-900 rounded-xl border border-slate-800 space-y-2 text-xs">
                <label className="text-slate-400 font-mono block">Merchant Risk Classification</label>
                <select
                  value={cfCategory}
                  onChange={(e) => setCfCategory(e.target.value)}
                  className="w-full bg-slate-850 border border-slate-700 rounded-lg p-2 text-slate-100 outline-none cursor-pointer"
                >
                  <option value="grocery">Grocery (Low Risk - 0.05)</option>
                  <option value="fast_food">Fast Food (Low Risk - 0.10)</option>
                  <option value="electronics">Electronics (Medium - 0.50)</option>
                  <option value="luxury_goods">Luxury Goods (High - 0.65)</option>
                  <option value="crypto_exchange">Crypto Exchange (Critical - 0.85)</option>
                </select>
                <p className="text-[10px] text-slate-500 font-mono">
                  Adjusts empirical sector exposure.
                </p>
              </div>
            </div>

            {/* Re-scoring Comparison Output */}
            {cfResult && (
              <div className="p-5 bg-navy-900 rounded-xl border border-cyan-500/40 space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-xs font-bold font-mono text-cyan-300 uppercase tracking-wider">
                    Model Output Comparison
                  </h3>
                  <span className="text-[10px] font-mono text-slate-400">
                    Version: {cfResult.model_version}
                  </span>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 text-center">
                  <div className="p-3 bg-slate-900 rounded-lg border border-slate-800">
                    <span className="text-[11px] text-slate-400 block font-mono">ORIGINAL RISK SCORE</span>
                    <span className="text-2xl font-bold font-mono text-slate-200 mt-1 block">
                      {cfResult.original_risk_score.toFixed(1)}
                    </span>
                    <span className="text-[10px] text-slate-400 block mt-0.5">
                      {cfResult.original_category}
                    </span>
                  </div>

                  <div className="p-3 bg-slate-900 rounded-lg border border-slate-800">
                    <span className="text-[11px] text-slate-400 block font-mono">MODIFIED RISK SCORE</span>
                    <span className="text-2xl font-bold font-mono text-cyan-300 mt-1 block">
                      {cfResult.modified_risk_score.toFixed(1)}
                    </span>
                    <span className="text-[10px] text-cyan-400 block mt-0.5">
                      {cfResult.modified_category}
                    </span>
                  </div>

                  <div className="p-3 bg-slate-900 rounded-lg border border-slate-800">
                    <span className="text-[11px] text-slate-400 block font-mono">SCORE DELTA</span>
                    <span
                      className={`text-2xl font-bold font-mono mt-1 block ${
                        cfResult.risk_score_delta < 0
                          ? 'text-emerald-400'
                          : cfResult.risk_score_delta > 0
                          ? 'text-rose-400'
                          : 'text-slate-300'
                      }`}
                    >
                      {cfResult.risk_score_delta > 0 ? `+${cfResult.risk_score_delta}` : cfResult.risk_score_delta}
                    </span>
                    <span className="text-[10px] text-slate-400 block mt-0.5">
                      {cfResult.risk_score_delta < 0 ? 'Risk Reduced' : 'Risk Elevated'}
                    </span>
                  </div>
                </div>

                {/* Explicit Interpretability & Causality Caution Banner */}
                <div className="p-3 bg-amber-950/40 rounded-lg border border-amber-800/60 flex items-start gap-2.5 text-xs text-amber-300">
